    const headerRange = formatDateRange(data.entity.startDate, data.entity.endDate);
    const ganttData: GanttData = {
      raw: data,
      rows: det.rows,
      chartIssues: det.chartIssues,
      axis,
      headerRange,
      generatedAt,
      summary,
